CREATE OR REPLACE PROCEDURE AAAAAA
IS
 V_AAA VARCHAR2(3) := '100';
 V_BBB TABLE1.COLUMN1%TYPE; --
BEGIN
 FOR C_1 IN (
  SELECT COL1, COL2, COL3, COL4
  FROM TABLE2
  WHERE NVL(COL1,'N') = 'N' AND COL2 IN ('1','2','3')
  ORDER BY COL3
 ) LOOP
  V_BBB := '';
  SELECT COL1 INTO V_AAA FROM TABLE2 WHERE BBB = C_1.CCC;
  IF V_BBB = 'Y' THEN CONTINUE; END IF;
  IF C_1.COL1 IS NULL THEN
   UPDATE TABLE2
    SET COL1 = 'BBB', COL2 = SYSTIMESTAMP(0), COL3 = 'PGR IS NULL'
    WHERE COL3 = C_1.COL3;
   COMMIT; CONTINUE;
  END IF;
  MERGE INTO TABLE1 A
USING (
 SELECT V_AAA, C_1.COL1, C_1.col2 FROM DUAL
) B
ON (A.COL1 = B.COL1 AND A.col2 = B.col2)
WHEN MATCHED THEN UPDATE
 SET A.COL1 = C_1.COL1, A.col2 = C_1.COL2
WHEN NOT MATCHED THEN INSERT (COL1, COL2)
VALUES (,C_1.COL1, C_1.COL2);
  IF C_1.USR_ID IS NULL THEN
   UPDATE TABLE2 SET COL1 = 'F', COL1 = C_1.COL1, COL2 = C_1.COL2
    WHERE COL1 = C_1.COL2;
   COMMIT; CONTINUE;
  END IF;
  IF C_1.COL1 = 'AA' THEN
   MERGE INTO TABL2 A
USING (
 SELECT A.COL1, C_1.COL1, C_1.COL2, A.COL3,
        TO_CHAR(SYSDATE, 'YYYYMMDD') AS COL3
 FROM TALB2 A, TALB3 B
 WHERE A.COL1 = C_1.COL1 AND A.COL2 = C_1.COL2
) B
ON (A.COL1 = C_1.COL1 AND A.COL2 = C_1.COL2)
WHEN MATCHED THEN UPDATE SET A.COL1 = 'AAA', A.COL2 = 'BBB'
WHEN NOT MATCHED THEN INSERT (COL1, COL2)
VALUES (,C_1.COL1, C_1.COL2);
   UPDATE TABLE1 A
 SET COL1 = 'SSS', COL3 = 'BBB', COL2 = 'VVVV'
 WHERE COL3 = C_1.COL3 AND COL2 = C_1.COL2;
  END IF;
  MERGE INTO TABL2 A
USING (
 SELECT A.COL1, C_1.COL1, C_1.COL2, A.COL3,
        TO_CHAR(SYSDATE, 'YYYYMMDD') AS COL3
 FROM TALB2 A, TALB3 B
 WHERE A.COL1 = C_1.COL1 AND A.COL2 = C_1.COL2
) B
ON (A.COL1 = C_1.COL1 AND A.COL2 = C_1.COL2)
WHEN MATCHED THEN UPDATE SET A.COL1 = 'AAA', A.COL2 = 'BBB'
WHEN NOT MATCHED THEN INSERT (COL1, COL2)
VALUES (,C_1.COL1, C_1.COL2);
  UPDATE TABLE1 A
 SET COL1 = 'SSS', COL3 = 'BBB', COL2 = 'VVVV'
 WHERE COL3 = C_1.COL3 AND COL2 = C_1.COL2;
  UPDATE TABLE1 A
 SET COL1 = 'SSS', COL3 = 'BBB', COL2 = 'VVVV'
 WHERE COL3 = C_1.COL3 AND COL2 = C_1.COL2;
  UPDATE TABLE1 A
 SET COL1 = 'SSS', COL3 = 'BBB', COL2 = 'VVVV'
 WHERE COL3 = C_1.COL3 AND COL2 = C_1.COL2;
  COMMIT;
 END LOOP;
 COMMIT;
EXCEPTION
 WHEN OTHERS THEN RAISE;
END;
/
